draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw cherries
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();

  // Draw heart
  ctx.fillStyle = 'pink';
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.bezierCurveTo(W/2 - 30, H/2 - 20, W/2 + 30, H/2 - 20, W/2, H/2 + 50);
  ctx.fill();

  // Draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 150, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 130);
  ctx.lineTo(W/2, H/2 - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 70);
  ctx.lineTo(W/2 - 30, H/2 - 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 70);
  ctx.lineTo(W/2 + 30, H/2 - 30);
  ctx.stroke();

  // Animate heart beat
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 50 + 10 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fillStyle = 'red';
  ctx.fill();

  ctx.restore();
}
